import { MenuHeader, MenuItem } from '@kerfjs/ui/menu';

export function mountNavigation(target: HTMLElement, app: { go(id: string): void }) {
  target.className = 'kui-sidebar';
  target.innerHTML = `<div class="kui-sidebar-section" data-primary></div><div class="kui-sidebar-section" data-secondary></div><section class="kui-sidebar-surface" aria-label="Current workspace"><strong>Northstar</strong><span>12 members</span></section><footer class="sidebar-footer"><button type="button" data-action="settings">Settings</button><button type="button" data-action="help">Help</button></footer>`;
  const primary = target.querySelector('[data-primary]')!;
  MenuHeader({ target: primary, label: 'Workspace' });
  MenuItem({ target: primary, label: 'Overview', icon: 'home', selected: true, onSelect: () => app.go('overview') });
  MenuItem({ target: primary, label: 'Notes', onSelect: () => app.go('notes') });
  const secondary = target.querySelector('[data-secondary]')!;
  MenuHeader({ target: secondary, label: 'Manage' });
  MenuItem({ target: secondary, label: 'Members', icon: 'users', onSelect: () => app.go('members') });
  MenuItem({ target: secondary, label: 'Billing', disabled: true, onSelect: () => undefined });
  const onAction = (event: Event) => { const id = (event.target as HTMLElement).closest<HTMLButtonElement>('[data-action]')?.dataset.action; if (id) app.go(id); };
  target.addEventListener('click', onAction);
  return () => target.removeEventListener('click', onAction);
}

